X=/tmp/e1v1; mkdir -p $X; rm -f $X/port
curl -s -m 240 https://nextgit-platform.john-b7d.workers.dev/proposals -o $X/props.json
jq -e '.ok == true and (.proposals|length) >= 5 and ((. | keys | sort) == ["base","conflicts","ok","proposals","ref","summary"]) and (all(.proposals[]; .repo | startswith("agent-"))) and (.summary.proposals == (.proposals|length))' $X/props.json > /dev/null || { echo "live /proposals fixture failed validation"; exit 1; }
FIX=$X/props.json PORTF=$X/port node -e 'const http = require("http"), fs = require("fs"), path = require("path");
const fix = fs.readFileSync(process.env.FIX);
const post = process.env.POSTFIX ? fs.readFileSync(process.env.POSTFIX) : null;
const client = process.env.CLIENT || null;
const failp = Number(process.env.FAILP || 0), faile = process.env.FAILE === "1", evflip = process.env.EVFLIP === "1", landn = Number(process.env.LANDN || 0);
let propsN = 0, evN = 0, landN = 0, landed = false;
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" };
const jout = (s, o) => { s.setHeader("content-type", "application/json"); s.end(JSON.stringify(o)); };
const APP = `<script type="module" src="app.js"></script>`;
const INJ = `<script type="module" src="/__client.js"></script>` + APP;
http.createServer((q, s) => {
  const p = new URL(q.url, "http://x").pathname;
  if (p === "/proposals") { propsN++; if (propsN <= failp) { s.statusCode = 500; return s.end("fail"); } s.setHeader("content-type", "application/json"); return s.end(landed && post ? post : fix); }
  if (p === "/events") { if (faile) { s.statusCode = 500; return s.end("fail"); } evN++; const A = { type: "push", repo: "agent-2", at: "2026-10-07T10:00:01Z" }; const B = { type: "push", repo: "agent-3", at: "2026-10-07T10:00:02Z" }; return jout(s, { ok: true, events: evflip ? (evN <= 1 ? [A] : [B, A]) : [] }); }
  if (p === "/land") { landN++; if (landN <= landn) { s.statusCode = 500; return s.end(JSON.stringify({ ok: false, error: "boom" })); } landed = true; return jout(s, { ok: true, landed: { commit: "0123456789abcdef" } }); }
  if (p === "/merge") return jout(s, { ok: true, merge: { status: "clean", files: [{ path: "src/auth.ts", action: "modify", result: "merged", merged: "merged text" }] } });
  if (p === "/judge") return jout(s, { ok: true, judgments: [], skipped: [] });
  if (p === "/__client.js") { s.setHeader("content-type", "text/javascript"); return s.end(client || ""); }
  const rel = p === "/" ? "index.html" : p.slice(1);
  const f = path.normalize(path.join("platform/ui", rel));
  if (rel.indexOf("..") >= 0 || !f.startsWith(path.join("platform", "ui")) || !fs.existsSync(f) || !fs.statSync(f).isFile()) { s.statusCode = 404; return s.end(); }
  const ext = path.extname(f);
  if (ext === ".html" && client) { const h = fs.readFileSync(f, "utf8").replace(APP, INJ); s.setHeader("content-type", "text/html"); return s.end(h); }
  s.setHeader("content-type", types[ext] || "application/octet-stream"); s.end(fs.readFileSync(f));
}).listen(0, "127.0.0.1", function() { fs.writeFileSync(process.env.PORTF, "" + this.address().port); });' > $X/srv.log 2>&1 & SRV=$!
for i in $(seq 40); do test -s $X/port && break; sleep 0.25; done
PORT=$(cat $X/port)
google-chrome --headless=new --disable-gpu --no-sandbox --virtual-time-budget=8000 --dump-dom "http://127.0.0.1:$PORT/" 2>/dev/null > $X/dom.html
kill $SRV 2>/dev/null
D=$X/dom.html F=$X/props.json node -e '
const fs=require("fs");
const fix=JSON.parse(fs.readFileSync(process.env.F,"utf8"));
const dom=fs.readFileSync(process.env.D,"utf8");
const fail=(m)=>{console.error("FAIL: "+m);process.exit(1);};
const props=fix.proposals;
if(!(props.length>=5))fail("expected >=5 concurrent proposals, got "+props.length);
const cards=[...dom.matchAll(/id="card-(agent-[A-Za-z0-9._-]+)"/g)].map((m)=>m[1]);
if(cards.length!==props.length)fail("rendered cards "+cards.length+" != proposals "+props.length);
for(const p of props){if(cards.indexOf(p.repo)<0)fail("missing card for "+p.repo);}
const meta=dom.match(/id="proposals-meta"[^>]*>([^<]*)</);
if(!meta||meta[1].trim()!==props.length+" active")fail("proposals meta not exact: "+(meta?meta[1]:null));
if(!/id="conflicts-list"/.test(dom))fail("conflict map container missing");
if((fix.conflicts||[]).length>0&&!/conflict-card/.test(dom))fail("conflict map not rendered at rest");
if(/pagination|load-more|page-next|page-prev|data-page=/.test(dom))fail("pagination artifacts present");
console.log("OK FR-1: "+cards.length+" cards from one response; no pagination; map visible at rest");
'

