for i in $(seq 40); do test -s $X/port && break; sleep 0.25; done
PORT=$(cat $X/port)
google-chrome --headless=new --disable-gpu --no-sandbox --virtual-time-budget=8000 --dump-dom "http://127.0.0.1:$PORT/" 2>/dev/null > $X/dom.html
kill $SRV 2>/dev/null
D=$X/dom.html F=$X/props.json node -e '
const fs=require("fs");
const fix=JSON.parse(fs.readFileSync(process.env.F,"utf8"));
const dom=fs.readFileSync(process.env.D,"utf8");
const fail=(m)=>{console.error("FAIL: "+m);process.exit(1);};
const esc=(s)=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").split(String.fromCharCode(39)).join("&#039;");
const pieces=dom.split(/id="card-/);
const cards={};
for(let i=1;i<pieces.length;i++){const nm=pieces[i].match(/^[A-Za-z0-9._-]+/);if(nm)cards[nm[0]]=pieces[i];}
const props=fix.proposals;
for(const p of props){
const c=cards[p.repo];
if(!c)fail("no card for "+p.repo);
if(c.indexOf("class=\"proposal-repo-title\">"+p.repo+"<")<0)fail("repo title missing on "+p.repo);
if(p.intent){if(c.indexOf(esc(p.intent))<0)fail("intent missing on "+p.repo);}else{if(c.indexOf("intent-label")>=0)fail("intent label rendered with no intent on "+p.repo);}
const st=p.stats||{};
const nf=(st.files!=null?st.files:(p.files||[]).length);
if(c.indexOf(">"+nf+"</span> files")<0)fail("file count missing on "+p.repo);
if(c.indexOf(">+"+(st.additions!=null?st.additions:0)+"</span>")<0)fail("additions stat missing on "+p.repo);
if(c.indexOf(">-"+(st.deletions!=null?st.deletions:0)+"</span>")<0)fail("deletions stat missing on "+p.repo);
const rows=c.split(/class="file-row"/).slice(1);
for(const f of (p.files||[])){
const row=rows.find((r)=>r.indexOf("title=\""+esc(f.path)+"\"")>=0);
if(!row)fail("file row missing "+p.repo+" "+f.path);
if(row.indexOf("file-status-indicator status-"+String(f.status||"modified").toLowerCase())<0)fail("status missing "+p.repo+" "+f.path);
if(f.additions!=null&&row.indexOf(">+"+f.additions+"<")<0)fail("adds missing "+p.repo+" "+f.path);
if(f.deletions!=null&&row.indexOf(">-"+f.deletions+"<")<0)fail("dels missing "+p.repo+" "+f.path);
if(f.secret){
if(row.indexOf("badge-secret")<0)fail("secret badge missing "+p.repo+" "+f.path);
if(row.indexOf("btn-file-diff")>=0)fail("secret row offers view diff "+p.repo+" "+f.path);
for(const k of (f.keys||[]))if(row.indexOf(">"+esc(k)+"<")<0)fail("secret key missing "+k+" on "+p.repo);
}else{
if(row.indexOf("btn-file-diff")<0)fail("view diff missing "+p.repo+" "+f.path);
}
}
const landed=p.landing&&p.landing.status==="landed";
if(!landed){
if(c.indexOf("btn-preview-merge")<0)fail("preview merge missing on "+p.repo);
if(c.indexOf(">preview merge<")<0)fail("preview merge label wrong on "+p.repo);
if(c.indexOf("data-action=\"start-land\"")<0)fail("land action missing on "+p.repo);
if(c.indexOf(">Land into demo<")<0)fail("land label wrong on "+p.repo);
}
}
console.log("OK FR-2: card anatomy verified for "+props.length+" cards");
'

